<template><el-container class="app-shell"><el-aside width="232px" class="app-sidebar desktop-sidebar"><AppNavigation/></el-aside><el-container><el-header class="app-header"><div class="title-row"><el-button class="mobile-menu-button" text @click="mobileMenu=true">☰</el-button><div><div class="page-title">{{pageTitle}}</div><div class="page-desc">今天也把重要的事情放到系统里</div></div></div><div class="header-actions"><el-input v-model="searchKeyword" class="global-search" placeholder="全局搜索" clearable @keyup.enter="search"><template #append><el-button @click="search">搜索</el-button></template></el-input><el-button type="primary" @click="quickNoteVisible=true">快捷新增</el-button><el-dropdown @command="handleUserCommand"><el-avatar class="user-avatar">{{avatarText}}</el-avatar><template #dropdown><el-dropdown-menu><el-dropdown-item disabled>{{displayName}}</el-dropdown-item><el-dropdown-item command="logout" divided>退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></el-header><el-main class="app-main"><router-view/></el-main></el-container></el-container><el-drawer v-model="mobileMenu" direction="ltr" size="260px" :with-header="false"><AppNavigation @navigate="mobileMenu=false"/></el-drawer><el-dialog v-model="quickNoteVisible" title="快捷记录" width="min(520px, 92vw)" @closed="quickNoteContent=''"><el-input v-model="quickNoteContent" type="textarea" :rows="5" maxlength="2000" show-word-limit placeholder="先记下来，稍后再整理……"/><template #footer><el-button @click="quickNoteVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveQuickNote">保存</el-button></template></el-dialog><el-dialog v-model="searchVisible" title="全局搜索" width="min(760px, 94vw)"><el-input v-model="searchKeyword" placeholder="搜索任务、开发日志、账单、学习总结、记录和股票" @keyup.enter="search"/><div class="search-results"><el-empty v-if="!searchResults.length" description="未找到相关内容"/><button v-for="item in searchResults" :key="item.type+item.id" class="search-item" @click="goResult(item)"><el-tag size="small">{{typeName(item.type)}}</el-tag><div><b>{{item.title}}</b><p>{{item.snippet}}</p></div><small>{{formatTime(item.occurredAt)}}</small></button></div></el-dialog></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{computed,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{logout}from'@/api/auth';import{createQuickNote}from'@/api/quickNote';import{globalSearch,type SearchResult}from'@/api/productivity';import AppNavigation from'./AppNavigation.vue';const route=useRoute(),router=useRouter(),pageTitle=computed(()=>String(route.meta.title||'个人辅助系统')),quickNoteVisible=ref(false),quickNoteContent=ref(''),saving=ref(false),mobileMenu=ref(false),searchKeyword=ref(''),searchVisible=ref(false),searchResults=ref<SearchResult[]>([]);const storedUser=JSON.parse(localStorage.getItem('currentUser')||'{}')as{displayName?:string;username?:string},displayName=storedUser.displayName||storedUser.username||'用户',avatarText=computed(()=>displayName.slice(0,1));async function saveQuickNote(){const content=quickNoteContent.value.trim();if(!content){ElMessage.warning('请输入记录内容');return;}saving.value=true;try{await createQuickNote(content);ElMessage.success('已保存到待整理记录');quickNoteVisible.value=false;}finally{saving.value=false;}}async function search(){if(searchKeyword.value.trim().length<2){ElMessage.warning('至少输入 2 个字符');return;}searchResults.value=(await globalSearch(searchKeyword.value.trim())).data;searchVisible.value=true;}async function goResult(item:SearchResult){searchVisible.value=false;await router.push(item.route);}async function handleUserCommand(command:string){if(command!=='logout')return;try{await logout();}finally{localStorage.removeItem('token');localStorage.removeItem('currentUser');await router.replace('/login');}}const typeName=(type:string)=>({TASK:'任务',DEVLOG:'开发',FINANCE:'账单',QUICK_NOTE:'记录',LEARNING:'学习',STOCK:'股票'}[type]||type);const formatTime=(value:string)=>new Date(value).toLocaleString('zh-CN',{hour12:false});</script>
<style scoped>.title-row{display:flex;align-items:center;gap:8px}.mobile-menu-button{display:none;font-size:22px}.global-search{width:280px}.search-results{max-height:520px;overflow:auto;margin-top:12px}.search-item{width:100%;display:grid;grid-template-columns:70px 1fr 150px;gap:12px;text-align:left;align-items:start;border:0;border-bottom:1px solid #eee;background:white;padding:14px;cursor:pointer}.search-item:hover{background:#f8fafc}.search-item p{margin:6px 0;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.search-item small{text-align:right;color:#94a3b8}@media(max-width:768px){.desktop-sidebar{display:none}.mobile-menu-button{display:inline-flex}.app-header{padding:0 12px}.page-desc{display:none}.global-search{width:44px}.global-search :deep(input){display:none}.header-actions{gap:6px}.header-actions>.el-button{padding:8px}.app-main{padding:12px}.search-item{grid-template-columns:60px 1fr}.search-item small{display:none}}</style>
